// largest3.cpp - Largest of three numbers
#include <iostream>
using namespace std;

int main() {
    int a, b, c;
    cout << "Enter three numbers: ";
    cin >> a >> b >> c;

    int largest = a;
    if (b > largest) largest = b;
    if (c > largest) largest = c;

    cout << "Largest = " << largest << endl;
    return 0;
}

// factorial.cpp - Factorial of a number
#include <iostream>
using namespace std;

int main() {
    int n;
    long long fact = 1;
    cout << "Enter a number: ";
    cin >> n;

    for (int i = 1; i <= n; i++) {
        fact = fact * i;
    }
    cout << "Factorial of " << n << " = " << fact << endl;
    return 0;
}

// digitsum.cpp - Sum of digits
#include <iostream>
using namespace std;

int main() {
    int n, sum = 0;
    cout << "Enter a number: ";
    cin >> n;

    while (n > 0) {
        sum = sum + n % 10;   // last digit
        n = n / 10;           // remove last digit
    }
    cout << "Sum of digits = " << sum << endl;
    return 0;
}

// sumn.cpp - Two algorithms for 1 + 2 + ... + n
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "Enter n: ";
    cin >> n;

    // Algorithm A: loop (n additions)
    long long sumA = 0;
    for (int i = 1; i <= n; i++)
        sumA += i;

    // Algorithm B: formula (one calculation)
    long long sumB = (long long)n * (n + 1) / 2;

    cout << "Using loop    : " << sumA << endl;
    cout << "Using formula : " << sumB << endl;
    return 0;
}

// grade.cpp - Grade from percentage
#include <iostream>
using namespace std;

int main() {
    float marks;
    cout << "Enter percentage: ";
    cin >> marks;

    if (marks < 0 || marks > 100)
        cout << "Invalid marks" << endl;
    else if (marks >= 90)
        cout << "Grade A" << endl;
    else if (marks >= 75)
        cout << "Grade B" << endl;
    else if (marks >= 60)
        cout << "Grade C" << endl;
    else if (marks >= 33)
        cout << "Grade D" << endl;
    else
        cout << "Fail" << endl;
    return 0;
}

