#include <iostream>
using namespace std;

int main() {
    float bill, discount;
    cout << "Enter bill amount: ";
    cin >> bill;

    if (bill > 2000)
        discount = bill * 0.10;
    else if (bill > 1000)
        discount = bill * 0.05;
    else
        discount = 0;

    cout << "Discount     : Rs " << discount << endl;
    cout << "Final amount : Rs " << bill - discount << endl;
    return 0;
}
